using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Reflection;using System.Diagnostics;using System.Collections.Generic;using System.Globalization;using System.Runtime.InteropServices;using EanEtikety;
class PrintPreviewBenchmark {
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;static string dir;static readonly List<string> rows=new List<string>();static readonly List<double> gaps=new List<double>();static readonly Stopwatch beat=Stopwatch.StartNew();
 [DllImport("user32.dll")]static extern int GetGuiResources(IntPtr process,int kind);
 static T F<T>(object o,string n){return (T)o.GetType().GetField(n,Hidden).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,Hidden).Invoke(o,a);}
 static string N(double n){return n.ToString("0.###",CultureInfo.InvariantCulture);}
 static void Wait(PrintPanel p,Action start){int before=p.PreviewBuilds;start();var clock=Stopwatch.StartNew();while(p.PreviewBuilds==before){Application.DoEvents();System.Threading.Thread.Sleep(1);if(clock.ElapsedMilliseconds>60000)throw new Exception("Preview timeout: "+F<Label>(p,"info").Text);}if(!p.Ready)throw new Exception(F<Label>(p,"info").Text);}
 static void Record(string scenario,int iteration,PrintPanel p,double wall,double shell){var t=p.LastPreviewPerformance;rows.Add(string.Join(",",new[]{scenario,iteration.ToString(CultureInfo.InvariantCulture),N(wall),N(shell),N(t.CaptureMs),N(t.QueueMs),N(t.DiscoveryMs),N(t.SetupMs),N(t.InspectionMs),N(t.RenderMs),N(t.DeliveryMs),N(t.ApplyMs),N(t.TotalMs),t.ArtworkCacheHit?"1":"0",t.DriverGeometryReads.ToString(),t.CapabilityReads.ToString(),t.RenderedPages.ToString()}));}
 static void Sample(string scenario,int i,PrintPanel p,Action action){var clock=Stopwatch.StartNew();Wait(p,action);Record(scenario,i,p,clock.Elapsed.TotalMilliseconds,0);}
 static Form Window(MainForm editor,LabelSettings label,out PrintPanel panel){var f=(Form)Call(editor,"CreatePrintWindow",label);f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);panel=(PrintPanel)f.Controls[0];typeof(PrintPanel).GetField("initialPrinterName",Hidden).SetValue(panel,"Microsoft Print to PDF");return f;}
 [STAThread]static void Main(string[] args){dir=Path.GetFullPath(args[0]);Directory.CreateDirectory(dir);try{Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Control.CheckForIllegalCrossThreadCalls=true;rows.Add("scenario,iteration,wall_ms,shell_ms,capture_ms,queue_ms,discovery_ms,setup_ms,inspection_ms,render_ms,delivery_ms,apply_ms,total_ms,artwork_hit,geometry_reads,capability_reads,rendered_pages");
  var timer=new Timer{Interval=15};timer.Tick+=delegate{gaps.Add(beat.Elapsed.TotalMilliseconds);beat.Restart();};timer.Start();long memory=Process.GetCurrentProcess().PrivateMemorySize64;int handles=GetGuiResources(Process.GetCurrentProcess().Handle,0);
  using(var editor=new MainForm(Path.Combine(dir,"startup.xml"))){editor.StartPosition=FormStartPosition.Manual;editor.Location=new Point(-20000,-20000);editor.Show();Application.DoEvents();
   for(int i=0;i<4;i++){var clock=Stopwatch.StartNew();PrintPanel p;using(var f=Window(editor,LabelSettings.Default(),out p)){double shell=clock.Elapsed.TotalMilliseconds;Wait(p,()=>f.Show());Record(i==0?"first-window":"reopen",i,p,clock.Elapsed.TotalMilliseconds,shell);}}
   PrintPanel panel;using(var f=Window(editor,LabelSettings.Default(),out panel)){Wait(panel,()=>f.Show());for(int i=0;i<8;i++)Sample("repeat",i,panel,()=>panel.RefreshPreview());for(int i=0;i<8;i++)Sample("orientation",i,panel,()=>F<CheckBox>(panel,"landscape").Checked=!F<CheckBox>(panel,"landscape").Checked);for(int i=0;i<4;i++)Sample("calibration",i,panel,()=>F<NumericUpDown>(panel,"offsetX").Value=i%2==0?1:0);}
   var multi=LabelSettings.Default();multi.Copies=3;using(var f=Window(editor,multi,out panel)){Wait(panel,()=>f.Show());for(int i=0;i<9;i++)Sample("page",i,panel,()=>F<NumericUpDown>(panel,"page").Value=i%3+1==F<NumericUpDown>(panel,"page").Value?(i+1)%3+1:i%3+1);}
   Call(editor,"Apply",LabelSettings.Default());editor.Close();
  }
  timer.Stop();timer.Dispose();GC.Collect();GC.WaitForPendingFinalizers();File.WriteAllLines(Path.Combine(dir,"timings.csv"),rows);File.WriteAllLines(Path.Combine(dir,"ui-gaps-ms.txt"),gaps.ConvertAll(v=>N(v)));File.WriteAllText(Path.Combine(dir,"resources.txt"),"PrivateBytesBefore="+memory+"\nPrivateBytesAfter="+Process.GetCurrentProcess().PrivateMemorySize64+"\nGdiBefore="+handles+"\nGdiAfter="+GetGuiResources(Process.GetCurrentProcess().Handle,0)+"\nRuntime="+Environment.Version+"\nWindows="+Environment.OSVersion.Version+"\nProcessorCount="+Environment.ProcessorCount+"\nDriver=Microsoft Print to PDF\nNo physical print submitted.\n");File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS sequential preview benchmark; "+(rows.Count-1)+" samples; no physical print");
 }catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
}
